 OUTER APPLY (SELECT SUM(g.SoLuong) qty FROM dbo.GiaoDichKho g WHERE g.MaChiNhanh=t.MaChiNhanh AND g.MaPhuTung=t.MaPhuTung AND g.LoaiGiaoDich='XUAT' AND g.GhiChu=N'[DEMO-V02] Xuất vật tư cho hạng mục sửa chữa') x
 WHERE t.SoLuongTon<>o.SoLuongTon-ISNULL(x.qty,0)) THROW 51111, 'Stock ledger mismatch.', 1;

